        "testata": "Internazionale",
        "lingua_originale": "it",
        "titolo_orig": "Il cinema palestinese oggi appartiene alle registe",
        "testo_it": "Palestina: il successo internazionale delle registe cinematografiche che stanno ridefinendo il cinema locale.",
        "priorita": "Bassa",
        "id_gruppo": 22,
        "link": "https://www.internazionale.it/notizie/catherine-cornet/2026/06/06/registe-palestinesi",
        "orario": "05:46",
